// TH18 v1.00a Stage 6 Boss2 non-spell (st06bs.ecl.txt:233-314, helper184-232).
// Source t0 = B:248 timerReset; slot-0 interrupt HP4500/3000 -> BossCard2 (B:269).
// Entry (0,128): BossCard1's movePosTime(180,4,0,128) is long finished by its
// 4200-frame timeout; the timeout falls inside the stationary G loop.
// Training shell: controller enemy at (0,0) with body collision off; real boss at
// source (0,128) keeps source hurtbox 40x40 / hitbox 48x48. 120-frame opening buffer.
const TIME_LIMIT: int = 3122;     // 120 buffer + 3000 source timeout + 2 frame task phase
const SOURCE_LIMIT: int = 3000;   // source setInterrupt slot0 timeout (B:269)
const OPENING_BUFFER: int = 120;
const TH18_TALISMAN: int = 528;   // TH18 type 11 Talisman, base radius 2.8

// Source B:193-195: ANIM a=1 (handled by sh_dist), WAIT type 0x80000000 a=20,
// then VELTIME type 0x200000 a=60 with r=%L and s=-9999994 (keep entered angle).
xformdef TALISMAN_MOTION(target: fx) {
    wait(20);
    step_speed(target, 60 + 65536 * EASE_LINEAR);
}

// Source B:184-232 Boss1_at(A..L).  Source et slot B becomes this task's slot 0;
// every async lane has its own task emitter, so the three lanes do not share config.
async sub at_wave(color: int, c0: angle, d0: angle, de: angle, df: angle,
                  radius: fx, axis: angle, dh: angle, ratio: fx,
                  count: int, target: fx) {
    var rank: int = global(GVAR_RANK);
    // B:196-202: Easy doubles both angular steps, Normal scales them by 1.2.
    var de_i: int = de as int;
    var df_i: int = df as int;
    if rank == 0 { de_i = de_i * 2; df_i = df_i * 2; }
    if rank == 1 { de_i = de_i * 6 / 5; df_i = df_i * 6 / 5; }
    var dc: angle = de_i as angle;
    var dd: angle = df_i as angle;
    // B:218-227: Easy waits 2, Normal/Hard/Lunatic wait 1.
    var step: int = 1;
    if rank == 0 { step = 2; }

    sh_reset(0);
    sh_sprite(0, TH18_TALISMAN, color); // etSprite(B,11,A)
    sh_aim(0, 0);                       // etAim(B,1): mode 1 fixed direction
    sh_ring(0, 0);
    sh_count(0, 1, 1);                  // etCount(B,1,1)
    sh_speed(0, 1fx, 0fx);              // etSpeed(B,1,1), single speed layer
    sh_dist(0, -4fx);                   // ANIM a=1: -4 * initial speed (4px)
    sh_xform(0, TALISMAN_MOTION(target));

    for i in 0..count {
        // B:208-217 ins_94(M,N,D,G,H,J); H+=I; etOffset(M,N); etAngle(C,0);
        // etOn; C+=E; D+=F; validRad; wait.
        var pi: int = (d0 as int) % 65536;
        if pi > 32767 { pi = pi - 65536; }
        if pi < -32768 { pi = pi + 65536; }
        var hi: int = (axis as int) % 65536;
        if hi > 32767 { hi = hi - 65536; }
        if hi < -32768 { hi = hi + 65536; }
        var ti: int = pi - hi;
        ti = ti % 65536;
        if ti > 32767 { ti = ti - 65536; }
        if ti < -32768 { ti = ti + 65536; }
        var t: angle = ti as angle;
        var u: fx = radius * ratio * cos(t);
        var v: fx = radius * sin(t);
        var m: fx = u * cos(axis) - v * sin(axis);
        var n: fx = u * sin(axis) + v * cos(axis);
        var ai: int = (axis + dh) as int;
        ai = ai % 65536;
        if ai > 32767 { ai = ai - 65536; }
        if ai < -32768 { ai = ai + 65536; }
        axis = ai as angle;
        sh_offset(0, m, n);
        sh_angle(0, c0, 0deg);
        sh_fire(0);
        var ci: int = (c0 + dc) as int;
        ci = ci % 65536;
        if ci > 32767 { ci = ci - 65536; }
        if ci < -32768 { ci = ci + 65536; }
        c0 = ci as angle;
        var di: int = (d0 + dd) as int;
        di = di % 65536;
        if di > 32767 { di = di - 65536; }
        if di < -32768 { di = di + 65536; }
        d0 = di as angle;
        wait(step);
    }
}

// ---------------------------------------------------------------------------
// B:245 moveLimit(0,128,280,96): actual position x[-140,140], y[80,176];
// moveRand direction inner region x+-70, y[104,152].
// Shared slots: self_int(0)=next step count, self_fx(0/1)=logical cos/sin.
// ---------------------------------------------------------------------------
sub move_arm(duration: int, speed0: fx) {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < duration { speed = speed0 * ((duration - k) as fx) / (duration as fx); }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 80fx { ny = 80fx; }
    if ny > 176fx { ny = 176fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

// The main task arms step 1 at the moveRand call; this task continues k=2..duration,
// so the first source movement tick is not delayed by the async first-run frame.
async sub move_continue(duration: int, speed0: fx) {
    loop {
        move_arm(duration, speed0);
        if self_int(0) >= duration { return; }
        wait(1);
    }
}

sub card_move_rand() {
    // Source B:308 moveRand(100,0,0.6): R = pi*U -> BAM r; alpha branch per movement.md.
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 104fx {
        if a < 0 { a = -a; }
    } else if $self_y > 152fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    set_self_fx(0, cos(a as angle));
    set_self_fx(1, sin(a as angle));
    set_self_int(0, 0);
    move_arm(100, 0.6fx);
}

// Source B:235-314 Boss2: 90+80 prelude, then loop { three async lanes at
// B:286/296/306; wait 600; moveRand(100,0,0.6); wait 60 }.
async sub pattern() {
    wait(OPENING_BUFFER);
    var rank: int = global(GVAR_RANK);
    wait(90); // B:271
    // B:272 EffChargePoint3 is presentation only.
    wait(80); // B:273
    loop {
        // B:276/286: lane 1 speed 2.2 E, 2.0 N/H, 2.8 L.
        var target1: fx = 2.0fx;
        if rank == 0 { target1 = 2.2fx; }
        if rank == 3 { target1 = 2.8fx; }
        // B:296/306: lanes 2/3 speed 2.2 E/N/H, 3.0 L.
        var target23: fx = 2.2fx;
        if rank == 3 { target23 = 3.0fx; }
        spawn at_wave(8, 180deg, -90deg, 6deg, 10.6deg, 64fx, 90deg,
                      -3deg, 0.5fx, 600, target1);
        spawn at_wave(6, 0deg, 180deg, 6deg, 6.6deg, 64fx, -90deg,
                      2deg, 0.5fx, 600, target23);
        spawn at_wave(4, -90deg, 0deg, 6deg, 6.6deg, 64fx, -90deg,
                      2deg, 0.5fx, 600, target23);
        wait(600);        // B:307
        card_move_rand(); // B:308
        spawn move_continue(100, 0.6fx);
        wait(60);         // B:309
    }
}

async sub boss_main() {
    // Source common entry B:33-34; Boss2 entry position stays (0,128).
    set_invuln(65535);
    set_hurtbox(20fx); // source 40/40
    set_hitbox(24fx);  // source 48/48
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    move_vel(0, 0deg, 0fx, EASE_LINEAR);
    loop { wait(1); }
}

// Extra training-only phase controller at (0,0); it never carries the source boss
// judgement.  The real boss keeps source position, hitbox and body collision.
async sub controller() {
    set_enemy_flag(ENEMY_NO_BODY, 1);
    set_invuln(65535);
    _ = spawn_enemy(0fx, 128fx, 20500, 0, 0, 0, boss_main);
    loop { wait(600); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1, 0, 0, 0, controller);
    loop { wait(600); }
}
